<template>
 <view class="page-heading"><view><text class="page-title">我的精灵小伙伴</text><text class="page-subtitle">四种精灵主题风格随心切换，打造专属体验！</text></view></view>
 <view class="pet-house pet-workspace" :class="{'pet-house-dark':dark,'pet-house-reduced':theme.reduced}" :style="houseStyle">
  <view class="pet-house-hero"><PetScene :scene="scene" :current="pet.current" :pets="pet.all" :panorama="windowLayout.width>=840" :reduced="theme.reduced" :dark="dark" :high-contrast="theme.settings.highContrast" @choose="choose"/><CurrentPetHero class="pet-current-hero" :pet="pet.current" @action="openAction"/></view>
  <WPCard class="pet-theme-switch"><view class="section-heading"><text>主题切换</text><text class="small muted">只改变陪伴空间</text></view><view class="pet-theme-grid"><button v-for="id in elements" :key="id" role="button" tabindex="0" class="pet-theme-choice" :class="{selected:house.sceneId===id}" :aria-label="petHouseThemes[id].title" :aria-pressed="house.sceneId===id" @click="house.setScene(id)"><image class="pet-theme-thumbnail" :src="petHouseThemes[id].sceneAsset" mode="aspectFill" aria-hidden="true"/><view class="pet-theme-copy"><text class="strong">{{petHouseThemes[id].title}} <text v-if="house.sceneId===id" class="theme-check" aria-hidden="true">✓</text></text><text class="small muted">{{petHouseThemes[id].subtitle}}</text></view></button></view><text v-if="house.error" class="notice" role="status">{{house.error}}</text></WPCard>
  <view class="pet-selection"><WPPetCard v-for="p in pet.all" :key="p.element" :pet="p" :selected="pet.current.element===p.element" @choose="choose"/></view>
  <view id="pet-details" class="pet-action-workspace"><view class="pet-action-menu" role="group" aria-label="宠物屋功能"><button v-for="item in actions" :key="item.id" role="button" tabindex="0" class="pet-action-tab" :class="{selected:action===item.id}" :aria-pressed="action===item.id" @click="openAction(item.id)"><text aria-hidden="true">{{item.icon}}</text><text>{{item.label}}</text><text v-if="action===item.id" class="small" aria-hidden="true">✓</text></button></view>
  <view class="pet-action-panel">
   <WPCard v-if="action==='home'" class="pet-home-panel"><text class="section-title">精灵家园</text><text class="muted block">四个伙伴都在这里，选一位陪你探索单词。</text><view class="daily-task"><text>{{learning.todayAnswers.length>=3?'✓':'○'}} 认真练习 3 次</text><text class="small muted">今日 {{Math.min(3,learning.todayAnswers.length)}} / 3</text></view><view class="daily-task"><text>{{learning.todayAnswers.length>=5?'✓':'○'}} 完成 5 次学习</text><text class="small muted">今日 {{Math.min(5,learning.todayAnswers.length)}} / 5 · 额外 10 经验</text></view><view class="daily-task"><text>{{learning.todayAnswers.some(a=>a.mode==='spell'||a.mode==='dictation')?'✓':'○'}} 试一次拼写或听写</text></view><WPButton kind="secondary" @click="navigate('learn')">一起去学习 →</WPButton></WPCard>
   <WPCard v-if="action==='feed'" class="pet-growth pet-feed-panel"><view class="section-heading"><text>喂养{{pet.info.name}}</text><text class="small">◇ {{profile.db.gems}} 灵石</text></view><text class="small muted block">{{petMoods[pet.current.mood]}} · 亲密度 {{pet.current.affection}} / 100</text><view class="food-grid"><button v-for="food in foods" :key="food.id" role="button" tabindex="0" class="food-choice" :class="{selected:foodId===food.id}" :aria-pressed="foodId===food.id" @click="selectFood(food.id)"><text class="food-icon" aria-hidden="true">{{food.icon}}</text><text>{{food.name}}</text><text class="small muted">5 灵石 / 份</text><text v-if="foodId===food.id" class="small">✓ 已选</text></button></view><text class="small muted block">可分享 {{Math.floor(profile.db.gems/5)}} 份小点心 · 每个伙伴每天一份</text><view v-if="preview" class="feed-preview" role="region" aria-label="分享预览"><text class="strong block">把{{selectedFood.name}}分享给{{pet.info.name}}</text><text class="small block">消耗 5 灵石 · 亲密度最多 +5 · 经验不变</text><view class="feed-confirm-actions"><WPButton class="confirm-feed" :disabled="!canFeed" @click="confirmFeed">确认分享 · 5 灵石</WPButton><WPButton kind="quiet" @click="preview=null">取消</WPButton></view></view><WPButton v-else :disabled="!canFeed" @click="preview={element:pet.current.element,foodId}">{{pet.current.lastFedDate===today?'✓ 今天已分享':profile.db.gems<5?'学习后收获灵石':'预览分享小点心'}}</WPButton><text class="small muted block">成长经验来自学习，点心只增加亲密度。</text></WPCard>
   <WPCard v-if="action==='growth'" class="pet-growth-panel"><view class="section-heading"><text>精灵成长</text><text class="strong">Lv.{{pet.current.level}}</text></view><view class="context-line small"><text>升级经验</text><text>{{pet.current.exp%100}} / 100</text></view><WPProgress :value="pet.current.exp%100" :total="100" label="成长升级经验"/><view class="growth-track"><view v-for="(stage,i) in petStages" :key="stage.title" class="growth-step" :class="{reached:stageUnlocked(pet.current,i),locked:!stage.level}"><text aria-hidden="true">{{stageUnlocked(pet.current,i)?'✓':'⌑'}}</text><text>{{stage.title}}</text><text class="small">{{stage.level?'Lv.'+stage.level:'尚未开放'}}</text></view></view><view class="pet-growth-facts"><view><text class="strong">{{pet.current.exp}}</text><text class="small muted">累计经验</text></view><view><text class="strong">{{pet.current.affection}} / 100</text><text class="small muted">亲密度</text></view><view><text class="strong">{{profile.db.history.length}} 次</text><text class="small muted">本设备累计学习</text></view></view><text class="small muted block">认真学习会带来成长；休息不会损失经验或亲密度。</text><WPButton kind="secondary" @click="navigate('learn')">和{{pet.info.name}}一起去学习 →</WPButton></WPCard>
   <WPCard v-if="action==='dress'" class="pet-dress-panel"><text class="section-title">小小装扮</text><view class="dress-preview"><PetHousePetArt :element="pet.current.element" :stage="pet.current.evolutionStage" :cosmetic="pet.current.equippedCosmetics[0]"/></view><text class="small muted block">只是可爱的配饰，不影响学习奖励或成长速度。</text><button v-for="item in cosmetics" :key="item.id" role="button" :tabindex="pet.current.level<item.level?-1:0" class="cosmetic-button" :disabled="pet.current.level<item.level" :aria-pressed="pet.current.equippedCosmetics.includes(item.id)" @click="equip(item.id)"><text>{{item.name}}</text><text class="small muted">{{pet.current.level<item.level?'⌑ Lv.'+item.level+' 解锁':pet.current.equippedCosmetics.includes(item.id)?'✓ 已穿戴 · 点击取下':'穿戴 →'}}</text></button></WPCard>
   <WPCard v-if="action==='album'" class="pet-album-panel"><text class="section-title">成长相册</text><text class="small muted block">{{pet.info.name}}的阶段解锁图鉴 · 随学习成长</text><view class="pet-album-grid"><view v-for="(stage,i) in petStages" :key="stage.title" class="pet-album-entry" :class="{locked:!stageUnlocked(pet.current,i)}" :aria-label="stage.title+(stageUnlocked(pet.current,i)?'，已解锁':'，未解锁')"><view class="album-art"><PetHousePetArt v-if="stageUnlocked(pet.current,i)" :element="pet.current.element" :stage="i+1"/><text v-else class="album-lock" aria-hidden="true">⌑</text></view><text class="strong">{{stage.title}}</text><text class="small muted">{{stageUnlocked(pet.current,i)?'✓ 已解锁':stage.level?'⌑ Lv.'+stage.level+' 解锁':'尚未开放'}}</text></view></view><text class="small muted block">这是当前等级的解锁记录；目前没有按日期保存的成长照片。</text></WPCard>
  </view></view><text v-if="message" class="notice pet-house-notice" role="status">{{message}}</text>
 </view>
</template>
<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import WPButton from '../../components/wp-button/WPButton.vue'
import WPCard from '../../components/wp-card/WPCard.vue'
import WPProgress from '../../components/wp-progress/WPProgress.vue'
import WPPetCard from '../../components/wp-pet-card/WPPetCard.vue'
import PetScene from '../../components/pet-house/PetScene.vue'
import CurrentPetHero from '../../components/pet-house/CurrentPetHero.vue'
import PetHousePetArt from '../../components/pet-house/PetHousePetArt.vue'
import {usePetStore,cosmetics} from '../../stores/pet'
import {usePetHouseStore} from '../../stores/pet-house'
import {useProfileStore} from '../../stores/profile'
import {useLearningStore} from '../../stores/learning'
import {localDate} from '../../../packages/core_learning'
import {elements,type Element} from '../../../packages/pet_engine'
import {windowLayout} from '../../services/window'
import {navigate} from '../../services/navigation'
import {useThemeStore} from '../../stores/theme'
import {petHouseThemes,petHouseStyle,petMoods,petStages,stageUnlocked} from '../../styles/pet-house'
type Action='home'|'feed'|'growth'|'dress'|'album'
const pet=usePetStore(),profile=useProfileStore(),learning=useLearningStore(),house=usePetHouseStore(),theme=useThemeStore()
const message=ref(''),foodId=ref('water'),action=ref<Action>('home'),preview=ref<{element:Element;foodId:string}|null>(null)
const foods=[{id:'water',name:'水滴果',icon:'◉'},{id:'pearl',name:'星光珍珠',icon:'◌'},{id:'leaf',name:'月光树叶',icon:'♧'},{id:'feather',name:'风之羽',icon:'✧'}]
const actions:{id:Action;label:string;icon:string}[]=[{id:'home',label:'家园',icon:'⌂'},{id:'feed',label:'喂食',icon:'♧'},{id:'growth',label:'成长',icon:'↗'},{id:'dress',label:'装扮',icon:'⋈'},{id:'album',label:'相册',icon:'▣'}]
const scene=computed(()=>petHouseThemes[house.sceneId]),dark=computed(()=>theme.settings.themeId==='oled'||theme.mode==='dark'),houseStyle=computed(()=>petHouseStyle(house.sceneId,dark.value,theme.settings.highContrast))
const today=computed(()=>{profile.db.gems;return localDate()}),canFeed=computed(()=>profile.db.gems>=5&&pet.current.lastFedDate!==today.value),selectedFood=computed(()=>foods.find(f=>f.id===foodId.value)!)
watch(()=>pet.current.element,()=>{preview.value=null;message.value=''})
function choose(element:Element){pet.choose(element)}
function openAction(id:Action){action.value=id;message.value='';if(windowLayout.width<600)nextTick(()=>uni.pageScrollTo({selector:'#pet-details',duration:theme.reduced?0:180}))}
function selectFood(id:string){foodId.value=id;preview.value={element:pet.current.element,foodId:id};message.value=''}
function confirmFeed(){if(!preview.value||preview.value.element!==pet.current.element||preview.value.foodId!==foodId.value)return;const name=selectedFood.value.name;message.value=pet.feed()?'✓ '+name+'已分享，亲密度最多 +5。':'今天已经分享过，或灵石还不够。';preview.value=null}
function equip(id:string){pet.equip(id);message.value=pet.current.equippedCosmetics.includes(id)?'✓ 装扮已穿戴。':'装扮已取下。'}
</script>
<style src="../../styles/pet-house.scss" lang="scss"></style>
